const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────\n// TENANTS (empresas clientes)\n// ─────────────────────────────────────────────\nmodel Tenant {\n  id              String  @id @default(cuid())\n  name            String\n  slug            String  @unique\n  logo_url        String?\n  primary_color   String  @default(\"#4F46E5\")\n  secondary_color String? // second brand color (gradient end)\n  tagline         String? // short brand phrase\n  industry        String? // sector / vertical\n  mission         String?\n  vision          String?\n  website         String?\n  tenant_type     String? @default(\"company\") // company | platform | network | branch\n  network_id      String? // parent tenant id for branch/franchise\n\n  plan       String @default(\"starter\") // starter | professional | enterprise\n  tier       String @default(\"company\") // employee | entrepreneur | company | platform\n  max_humans Int    @default(10)\n  max_agents Int    @default(20)\n  status     String @default(\"active\")\n\n  campus_config Json? // { campus_enabled, map_source, map_template, background_color, grid_size }\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  departments         Department[]\n  team_slots          TeamSlot[]\n  rooms               Room[]\n  spaces              Space[]\n  schedules           Schedule[]\n  messages            Message[]\n  files               File[]\n  audit_logs          AuditLog[]\n  notifications       Notification[]\n  integrations        Integration[]\n  onboarding_progress OnboardingProgress?\n  contacts            Contact[]\n  pipelines           Pipeline[]\n  knowledge_bases     KnowledgeBase[]\n  courses             Course[]\n  reports             Report[]\n  calendar_events     CalendarEvent[]\n  tasks               Task[]\n  goals               Goal[]\n  agent_conversations AgentConversation[]\n  agent_memories      AgentMemory[]\n  dashboard_configs   DashboardConfig[]\n  map_props           MapProp[]\n  strategic_purpose   StrategicPurpose?\n  key_success_factors KeySuccessFactor[]\n  focus_reports       FocusReport[]\n  feedback_reports    FeedbackReport[]\n  management_reports  ManagementReport[]\n  recognition_events  RecognitionEvent[]\n  goal_setup_statuses GoalSetupStatus[]\n}\n\n// ─────────────────────────────────────────────\n// DEPARTMENTS\n// ─────────────────────────────────────────────\nmodel Department {\n  id         String       @id @default(cuid())\n  tenant_id  String\n  tenant     Tenant       @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  name       String\n  dept_type  String? // sales | support | hr | training | ops | delivery | admin | accounting | marketing | bi | management\n  color      String       @default(\"#6366F1\")\n  icon       String?\n  parent_id  String?\n  parent     Department?  @relation(\"DeptHierarchy\", fields: [parent_id], references: [id])\n  children   Department[] @relation(\"DeptHierarchy\")\n  created_at DateTime     @default(now())\n\n  team_slots          TeamSlot[]\n  pipelines           Pipeline[]\n  knowledge_bases     KnowledgeBase[]\n  integrations        Integration[]\n  dashboard_configs   DashboardConfig[]\n  tasks               Task[]\n  key_success_factors KeySuccessFactor[]\n\n  @@index([tenant_id])\n}\n\n// ─────────────────────────────────────────────\n// TEAM SLOTS — humano O agente IA\n// ─────────────────────────────────────────────\nmodel TeamSlot {\n  id             String      @id @default(cuid())\n  tenant_id      String\n  tenant         Tenant      @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  department_id  String?\n  department     Department? @relation(fields: [department_id], references: [id])\n  reports_to_id  String?\n  reports_to     TeamSlot?   @relation(\"TeamHierarchy\", fields: [reports_to_id], references: [id])\n  direct_reports TeamSlot[]  @relation(\"TeamHierarchy\")\n\n  name          String\n  type          SlotType   @default(HUMAN)\n  role          String     @default(\"employee\") // owner | admin | manager | employee\n  avatar_url    String?\n  avatar_config Json?\n  status        SlotStatus @default(OFFLINE)\n  position_x    Int?\n  position_y    Int?\n\n  // Solo humanos\n  email         String?   @unique\n  password_hash String?\n  access_token  String?   @unique\n  schedule_id   String?\n  schedule      Schedule? @relation(fields: [schedule_id], references: [id])\n  desk_config   Json? // widget layout / personal desk configuration\n  desk_access   String?   @default(\"FULL\") // FULL | LIGHT | NONE\n\n  // Solo agentes IA\n  agent_config  Json? // { model, instructions, tools[], limits, personality }\n  agent_scope   String? // personal | department | company\n  agent_role    String? // focus_agent | daily_assistant | department_agent | company_agent | ceo\n  owner_slot_id String? // for personal agents: their human owner's slot id\n  owner_slot    TeamSlot?  @relation(\"AgentOwner\", fields: [owner_slot_id], references: [id])\n  owned_agents  TeamSlot[] @relation(\"AgentOwner\")\n\n  permissions Json?\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  sent_messages          Message[]           @relation(\"SentMessages\")\n  received_messages      Message[]           @relation(\"ReceivedMessages\")\n  time_logs              TimeLog[]\n  audit_logs             AuditLog[]\n  notifications          Notification[]\n  tasks_owned            Task[]              @relation(\"TaskOwner\")\n  tasks_assigned         Task[]              @relation(\"TaskAssignee\")\n  goals                  Goal[]\n  calendar_events        CalendarEvent[]\n  contacts_owned         Contact[]\n  deals_owned            Deal[]\n  agent_memories         AgentMemory[]       @relation(\"AgentMemories\")\n  human_memories         AgentMemory[]       @relation(\"HumanMemories\")\n  conversations_as_agent AgentConversation[] @relation(\"AgentConversations\")\n  conversations_as_human AgentConversation[] @relation(\"HumanConversations\")\n  dashboard_configs      DashboardConfig[]\n  course_progress        CourseProgress[]\n  certifications         Certification[]\n  personal_integrations  Integration[]\n  ksf_relationships      KsfRelationship[]\n  key_success_factors    KeySuccessFactor[]\n  escalation_config      EscalationConfig?\n  goal_measurements      GoalMeasurement[]\n  focus_reports          FocusReport[]\n  feedback_reports       FeedbackReport[]\n  management_reports     ManagementReport[]\n  recognitions_given     RecognitionEvent[]  @relation(\"RecognizerSlot\")\n  recognitions_received  RecognitionEvent[]  @relation(\"RecognizedSlot\")\n  goal_setup_status      GoalSetupStatus?\n\n  @@index([tenant_id, type])\n  @@index([tenant_id, status])\n  @@index([email])\n  @@index([owner_slot_id])\n}\n\nenum SlotType {\n  HUMAN\n  AI_AGENT\n}\n\nenum SlotStatus {\n  ONLINE\n  OFFLINE\n  BUSY\n  AWAY\n}\n\n// ─────────────────────────────────────────────\n// SCHEDULES (horarios laborales)\n// ─────────────────────────────────────────────\nmodel Schedule {\n  id                String   @id @default(cuid())\n  tenant_id         String\n  tenant            Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  name              String\n  check_in_time     String\n  check_out_time    String\n  tolerance_minutes Int      @default(15)\n  work_days         Json // [\"MON\",\"TUE\",\"WED\",\"THU\",\"FRI\"]\n  created_at        DateTime @default(now())\n\n  team_slots TeamSlot[]\n\n  @@index([tenant_id])\n}\n\n// ─────────────────────────────────────────────\n// TIME LOGS (reloj checador)\n// ─────────────────────────────────────────────\nmodel TimeLog {\n  id           String    @id @default(cuid())\n  slot_id      String\n  slot         TeamSlot  @relation(fields: [slot_id], references: [id], onDelete: Cascade)\n  date         String\n  check_in     DateTime\n  check_out    DateTime?\n  status       String    @default(\"on_time\") // on_time | late | early_leave\n  location_lat Float?\n  location_lng Float?\n  device_info  String?\n  created_at   DateTime  @default(now())\n\n  @@index([slot_id, date])\n}\n\n// ─────────────────────────────────────────────\n// MESSAGES\n// ─────────────────────────────────────────────\nmodel Message {\n  id          String    @id @default(cuid())\n  tenant_id   String\n  tenant      Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  sender_id   String\n  sender      TeamSlot  @relation(\"SentMessages\", fields: [sender_id], references: [id])\n  receiver_id String?\n  receiver    TeamSlot? @relation(\"ReceivedMessages\", fields: [receiver_id], references: [id])\n  channel_id  String?\n\n  content    String\n  type       MessageType @default(CHAT)\n  metadata   Json?\n  read_at    DateTime?\n  created_at DateTime    @default(now())\n\n  @@index([tenant_id, type])\n  @@index([sender_id])\n  @@index([receiver_id])\n  @@index([tenant_id, created_at])\n}\n\nenum MessageType {\n  CHAT\n  EMAIL\n  POSTIT\n  ANNOUNCEMENT\n  AGENT_RESPONSE\n}\n\n// ─────────────────────────────────────────────\n// ROOMS (mapa de la oficina virtual)\n// ─────────────────────────────────────────────\nmodel Room {\n  id         String   @id @default(cuid())\n  tenant_id  String\n  tenant     Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  name       String\n  room_type  String // desk | department | meeting | library | break | network | custom\n  x          Int\n  y          Int\n  width      Int\n  height     Int\n  floor      Int      @default(1)\n  color      String   @default(\"#E0E7FF\")\n  is_active  Boolean  @default(true)\n  created_at DateTime @default(now())\n\n  @@index([tenant_id])\n}\n\n// ─────────────────────────────────────────────\n// SPACES & CAMERAS (espacios físicos con CCTV)\n// ─────────────────────────────────────────────\nmodel Space {\n  id         String    @id @default(cuid())\n  tenant_id  String\n  tenant     Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  name       String\n  type       SpaceType @default(OFFICE)\n  floor      Int       @default(1)\n  created_at DateTime  @default(now())\n  updated_at DateTime  @updatedAt\n\n  cameras Camera[]\n\n  @@index([tenant_id])\n}\n\nmodel Camera {\n  id                    String       @id @default(cuid())\n  tenant_id             String\n  space_id              String\n  space                 Space        @relation(fields: [space_id], references: [id], onDelete: Cascade)\n  name                  String\n  type                  CameraType   @default(MJPEG)\n  status                CameraStatus @default(UNKNOWN)\n  stream_url_enc        String? // AES-256-GCM encrypted\n  snapshot_url_enc      String?\n  rtsp_url_enc          String?\n  cloud_embed_url       String?\n  refresh_interval_secs Int          @default(5)\n  created_at            DateTime     @default(now())\n  updated_at            DateTime     @updatedAt\n\n  @@index([tenant_id])\n  @@index([space_id])\n}\n\nenum SpaceType {\n  OFFICE\n  MEETING_ROOM\n  RECEPTION\n  WAREHOUSE\n  EXTERIOR\n  OTHER\n}\n\nenum CameraType {\n  MJPEG\n  SNAPSHOT\n  RTSP\n  CLOUD\n}\n\nenum CameraStatus {\n  ONLINE\n  OFFLINE\n  ERROR\n  UNKNOWN\n}\n\n// ─────────────────────────────────────────────\n// FILES\n// ─────────────────────────────────────────────\nmodel File {\n  id          String   @id @default(cuid())\n  tenant_id   String\n  tenant      Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  uploader_id String\n  name        String\n  url         String\n  size_bytes  Int\n  mime_type   String\n  folder_path String   @default(\"/\")\n  is_shared   Boolean  @default(false)\n  access_list Json?\n  created_at  DateTime @default(now())\n\n  @@index([tenant_id])\n  @@index([uploader_id])\n}\n\n// ─────────────────────────────────────────────\n// NOTIFICATIONS\n// ─────────────────────────────────────────────\nmodel Notification {\n  id         String   @id @default(cuid())\n  slot_id    String\n  slot       TeamSlot @relation(fields: [slot_id], references: [id], onDelete: Cascade)\n  tenant_id  String\n  tenant     Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  type       String\n  title      String\n  content    String\n  action_url String?\n  read       Boolean  @default(false)\n  created_at DateTime @default(now())\n\n  @@index([slot_id, read])\n}\n\n// ─────────────────────────────────────────────\n// INTEGRATIONS\n// ─────────────────────────────────────────────\nmodel Integration {\n  id                String      @id @default(cuid())\n  tenant_id         String\n  tenant            Tenant      @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  owner_slot_id     String?\n  owner_slot        TeamSlot?   @relation(fields: [owner_slot_id], references: [id])\n  dept_id           String?\n  dept              Department? @relation(fields: [dept_id], references: [id])\n  integration_scope String      @default(\"tenant\") // tenant | department | personal\n  provider          String // microsoft365 | google | gohighlevel | claude | n8n | whatsapp | stripe | chatwoot | meta\n  status            String      @default(\"disconnected\")\n  credentials_enc   String?\n  scope             Json?\n  config            Json?\n  last_sync_at      DateTime?\n  connected_at      DateTime?\n  created_at        DateTime    @default(now())\n  updated_at        DateTime    @updatedAt\n\n  @@index([tenant_id, provider])\n  @@index([owner_slot_id])\n  @@index([dept_id])\n}\n\n// ─────────────────────────────────────────────\n// AUDIT LOGS\n// ─────────────────────────────────────────────\nmodel AuditLog {\n  id        String    @id @default(cuid())\n  tenant_id String\n  tenant    Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  actor_id  String?\n  actor     TeamSlot? @relation(fields: [actor_id], references: [id])\n\n  action        String\n  resource_type String\n  resource_id   String?\n  payload       Json?\n  ip_address    String?\n  device_info   String?\n  timestamp     DateTime @default(now())\n\n  @@index([tenant_id, timestamp])\n  @@index([actor_id])\n  @@index([tenant_id, action])\n  @@index([resource_type, resource_id])\n}\n\n// ─────────────────────────────────────────────\n// ONBOARDING PROGRESS\n// ─────────────────────────────────────────────\nmodel OnboardingProgress {\n  id              String    @id @default(cuid())\n  tenant_id       String    @unique\n  tenant          Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  current_step    Int       @default(0)\n  steps_completed Json      @default(\"[]\")\n  template_used   String?\n  completed_at    DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n}\n\n// ─────────────────────────────────────────────\n// INDUSTRY TEMPLATES (catálogo en BD)\n// ─────────────────────────────────────────────\nmodel IndustryTemplate {\n  id           String   @id @default(cuid())\n  slug         String   @unique\n  display_name String\n  departments  Json\n  rooms        Json\n  agent_slots  Json\n  created_at   DateTime @default(now())\n}\n\n// ═════════════════════════════════════════════\n// SEGUNDO CEREBRO — MEMORIA DE AGENTES\n// ═════════════════════════════════════════════\n\nmodel AgentMemory {\n  id            String    @id @default(cuid())\n  tenant_id     String\n  tenant        Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  agent_id      String\n  agent         TeamSlot  @relation(\"AgentMemories\", fields: [agent_id], references: [id], onDelete: Cascade)\n  owner_slot_id String?\n  owner_slot    TeamSlot? @relation(\"HumanMemories\", fields: [owner_slot_id], references: [id])\n\n  memory_type   String // factual | episodic | preference | goal | relationship | skill | context\n  content       String\n  source_type   String?\n  source_id     String?\n  importance    Int       @default(5)\n  last_accessed DateTime?\n  access_count  Int       @default(0)\n  expires_at    DateTime?\n  created_at    DateTime  @default(now())\n  updated_at    DateTime  @updatedAt\n\n  @@index([agent_id])\n  @@index([owner_slot_id])\n  @@index([tenant_id, memory_type])\n  @@index([importance])\n}\n\nmodel AgentConversation {\n  id         String    @id @default(cuid())\n  tenant_id  String\n  tenant     Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  agent_id   String\n  agent      TeamSlot  @relation(\"AgentConversations\", fields: [agent_id], references: [id])\n  human_id   String\n  human      TeamSlot  @relation(\"HumanConversations\", fields: [human_id], references: [id])\n  session_id String    @default(cuid())\n  context    Json?\n  summary    String?\n  started_at DateTime  @default(now())\n  ended_at   DateTime?\n  created_at DateTime  @default(now())\n\n  messages AgentMessage[]\n\n  @@index([agent_id])\n  @@index([human_id])\n  @@index([tenant_id])\n  @@index([session_id])\n}\n\nmodel AgentMessage {\n  id              String            @id @default(cuid())\n  conversation_id String\n  conversation    AgentConversation @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  role            String // user | assistant | system | tool\n  content         String\n  tool_calls      Json?\n  tool_results    Json?\n  tokens_used     Int?\n  created_at      DateTime          @default(now())\n\n  @@index([conversation_id])\n  @@index([conversation_id, created_at])\n}\n\n// ═════════════════════════════════════════════\n// PRODUCTIVIDAD — TAREAS, METAS, CALENDARIO\n// ═════════════════════════════════════════════\n\nmodel Task {\n  id            String      @id @default(cuid())\n  tenant_id     String\n  tenant        Tenant      @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  owner_id      String\n  owner         TeamSlot    @relation(\"TaskOwner\", fields: [owner_id], references: [id])\n  assignee_id   String?\n  assignee      TeamSlot?   @relation(\"TaskAssignee\", fields: [assignee_id], references: [id])\n  department_id String?\n  department    Department? @relation(fields: [department_id], references: [id])\n\n  title        String\n  description  String?\n  status       String    @default(\"pending\") // pending | in_progress | completed | cancelled\n  priority     String    @default(\"medium\") // low | medium | high | urgent\n  due_date     DateTime?\n  completed_at DateTime?\n  tags         Json?\n  created_at   DateTime  @default(now())\n  updated_at   DateTime  @updatedAt\n\n  @@index([tenant_id, status])\n  @@index([owner_id])\n  @@index([assignee_id])\n  @@index([department_id])\n}\n\nmodel Goal {\n  id        String   @id @default(cuid())\n  tenant_id String\n  tenant    Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  slot_id   String\n  slot      TeamSlot @relation(fields: [slot_id], references: [id], onDelete: Cascade)\n\n  title         String\n  description   String?\n  goal_type     String    @default(\"personal\") // personal | department | company\n  target_value  Float?\n  current_value Float?\n  unit          String?\n  period        String    @default(\"monthly\") // daily | weekly | monthly | quarterly | yearly\n  start_date    DateTime?\n  end_date      DateTime?\n  status        String    @default(\"active\") // active | completed | paused | cancelled\n  created_at    DateTime  @default(now())\n  updated_at    DateTime  @updatedAt\n\n  @@index([slot_id])\n  @@index([tenant_id, status])\n}\n\nmodel CalendarEvent {\n  id           String   @id @default(cuid())\n  tenant_id    String\n  tenant       Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  organizer_id String\n  organizer    TeamSlot @relation(fields: [organizer_id], references: [id])\n\n  title       String\n  description String?\n  start_at    DateTime\n  end_at      DateTime\n  all_day     Boolean  @default(false)\n  location    String?\n  attendees   Json?\n  external_id String?\n  provider    String? // google | microsoft | internal\n  recurrence  Json?\n  status      String   @default(\"confirmed\") // confirmed | tentative | cancelled\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  @@index([tenant_id])\n  @@index([organizer_id])\n  @@index([start_at])\n}\n\n// ─────────────────────────────────────────────\n// DASHBOARD\n// ─────────────────────────────────────────────\nmodel DashboardConfig {\n  id        String      @id @default(cuid())\n  tenant_id String\n  tenant    Tenant      @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  slot_id   String?\n  slot      TeamSlot?   @relation(fields: [slot_id], references: [id])\n  dept_id   String?\n  dept      Department? @relation(fields: [dept_id], references: [id])\n\n  name       String\n  layout     Json?\n  is_default Boolean  @default(false)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  widgets DashboardWidget[]\n\n  @@index([slot_id])\n  @@index([dept_id])\n  @@index([tenant_id])\n}\n\nmodel DashboardWidget {\n  id           String          @id @default(cuid())\n  dashboard_id String\n  dashboard    DashboardConfig @relation(fields: [dashboard_id], references: [id], onDelete: Cascade)\n  tenant_id    String\n\n  widget_type String // metric | chart | list | clock | calendar | tasks | pipeline | map | contacts | kpi | agent_chat | team_status | goals\n  title       String\n  config      Json // data source, filters, display options\n  position    Json // { x, y, w, h }\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  @@index([dashboard_id])\n}\n\n// ═════════════════════════════════════════════\n// CRM\n// ═════════════════════════════════════════════\n\nmodel Contact {\n  id            String    @id @default(cuid())\n  tenant_id     String\n  tenant        Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  owner_slot_id String?\n  owner_slot    TeamSlot? @relation(fields: [owner_slot_id], references: [id])\n\n  first_name    String\n  last_name     String?\n  email         String?\n  phone         String?\n  company       String?\n  position      String?\n  status        String  @default(\"lead\") // lead | prospect | customer | churned | partner\n  tags          Json?\n  custom_fields Json?\n\n  ghl_id             String?\n  chatwoot_id        String?\n  stripe_customer_id String?\n  meta_psid          String?\n\n  last_contact_at DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  activities ContactActivity[]\n  deals      Deal[]\n\n  @@index([tenant_id])\n  @@index([owner_slot_id])\n  @@index([email])\n  @@index([phone])\n  @@index([tenant_id, status])\n}\n\nmodel ContactActivity {\n  id         String  @id @default(cuid())\n  contact_id String\n  contact    Contact @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n  tenant_id  String\n  actor_id   String?\n\n  activity_type String // note | call | email | message | meeting | task | deal_update | payment\n  content       String\n  metadata      Json?\n  created_at    DateTime @default(now())\n\n  @@index([contact_id])\n  @@index([tenant_id, activity_type])\n}\n\nmodel Pipeline {\n  id            String      @id @default(cuid())\n  tenant_id     String\n  tenant        Tenant      @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  department_id String?\n  department    Department? @relation(fields: [department_id], references: [id])\n\n  name          String\n  description   String?\n  pipeline_type String   @default(\"sales\") // sales | support | hr | custom\n  is_active     Boolean  @default(true)\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  stages PipelineStage[]\n  deals  Deal[]\n\n  @@index([tenant_id])\n}\n\nmodel PipelineStage {\n  id          String   @id @default(cuid())\n  pipeline_id String\n  pipeline    Pipeline @relation(fields: [pipeline_id], references: [id], onDelete: Cascade)\n  tenant_id   String\n\n  name        String\n  color       String   @default(\"#6366F1\")\n  order_index Int\n  automations Json?\n  created_at  DateTime @default(now())\n\n  deals Deal[]\n\n  @@index([pipeline_id])\n}\n\nmodel Deal {\n  id          String        @id @default(cuid())\n  tenant_id   String\n  pipeline_id String\n  pipeline    Pipeline      @relation(fields: [pipeline_id], references: [id])\n  stage_id    String\n  stage       PipelineStage @relation(fields: [stage_id], references: [id])\n  contact_id  String\n  contact     Contact       @relation(fields: [contact_id], references: [id])\n  owner_id    String\n  owner       TeamSlot      @relation(fields: [owner_id], references: [id])\n\n  title          String\n  value          Float?\n  currency       String    @default(\"MXN\")\n  status         String    @default(\"open\") // open | won | lost\n  expected_close DateTime?\n  closed_at      DateTime?\n  notes          String?\n  created_at     DateTime  @default(now())\n  updated_at     DateTime  @updatedAt\n\n  @@index([tenant_id, status])\n  @@index([stage_id])\n  @@index([contact_id])\n  @@index([owner_id])\n}\n\n// ═════════════════════════════════════════════\n// BASE DE CONOCIMIENTO\n// ═════════════════════════════════════════════\n\nmodel KnowledgeBase {\n  id            String      @id @default(cuid())\n  tenant_id     String\n  tenant        Tenant      @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  dept_id       String?\n  dept          Department? @relation(fields: [dept_id], references: [id])\n  owner_slot_id String?\n\n  name        String\n  description String?\n  kb_scope    String   @default(\"company\") // personal | department | company\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  chunks KnowledgeChunk[]\n\n  @@index([tenant_id])\n  @@index([dept_id])\n}\n\nmodel KnowledgeChunk {\n  id        String        @id @default(cuid())\n  kb_id     String\n  kb        KnowledgeBase @relation(fields: [kb_id], references: [id], onDelete: Cascade)\n  tenant_id String\n  file_id   String?\n\n  title      String?\n  content    String\n  source_url String?\n  metadata   Json?\n  created_at DateTime @default(now())\n\n  @@index([kb_id])\n  @@index([tenant_id])\n}\n\n// ═════════════════════════════════════════════\n// CAPACITACIÓN\n// ═════════════════════════════════════════════\n\nmodel Course {\n  id         String @id @default(cuid())\n  tenant_id  String\n  tenant     Tenant @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  created_by String\n\n  title       String\n  description String?\n  cover_url   String?\n  status      String   @default(\"draft\") // draft | published | archived\n  tags        Json?\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  modules        CourseModule[]\n  progress       CourseProgress[]\n  certifications Certification[]\n\n  @@index([tenant_id])\n  @@index([tenant_id, status])\n}\n\nmodel CourseModule {\n  id        String @id @default(cuid())\n  course_id String\n  course    Course @relation(fields: [course_id], references: [id], onDelete: Cascade)\n  tenant_id String\n\n  title            String\n  content          String\n  order_index      Int\n  duration_minutes Int?\n  resources        Json?\n  quiz             Json?\n  created_at       DateTime @default(now())\n\n  @@index([course_id])\n}\n\nmodel CourseProgress {\n  id        String   @id @default(cuid())\n  course_id String\n  course    Course   @relation(fields: [course_id], references: [id], onDelete: Cascade)\n  slot_id   String\n  slot      TeamSlot @relation(fields: [slot_id], references: [id], onDelete: Cascade)\n  tenant_id String\n\n  modules_completed Json      @default(\"[]\")\n  score             Float?\n  started_at        DateTime  @default(now())\n  completed_at      DateTime?\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n\n  @@unique([course_id, slot_id])\n  @@index([slot_id])\n}\n\nmodel Certification {\n  id        String   @id @default(cuid())\n  slot_id   String\n  slot      TeamSlot @relation(fields: [slot_id], references: [id], onDelete: Cascade)\n  tenant_id String\n  course_id String\n  course    Course   @relation(fields: [course_id], references: [id])\n\n  issued_at       DateTime  @default(now())\n  expires_at      DateTime?\n  certificate_url String?\n  created_at      DateTime  @default(now())\n\n  @@index([slot_id])\n  @@index([course_id])\n}\n\n// ═════════════════════════════════════════════\n// CAMPUS — MAPA INTERACTIVO\n// ═════════════════════════════════════════════\n\nmodel MapProp {\n  id        String  @id @default(cuid())\n  tenant_id String\n  tenant    Tenant  @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  room_id   String?\n\n  name          String\n  prop_type     String // desk | door | shelf | board | coffee | plant | locker | screen | custom\n  x             Int\n  y             Int\n  width         Int      @default(32)\n  height        Int      @default(32)\n  icon_url      String?\n  icon_default  String?\n  action_type   String // navigate_to | open_tool | start_meeting | open_url | trigger_event\n  action_target String\n  tooltip       String?\n  is_active     Boolean  @default(true)\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  @@index([tenant_id])\n  @@index([room_id])\n}\n\n// ═════════════════════════════════════════════\n// REPORTES\n// ═════════════════════════════════════════════\n\nmodel Report {\n  id        String @id @default(cuid())\n  tenant_id String\n  tenant    Tenant @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n\n  name         String\n  description  String?\n  report_type  String // attendance | productivity | sales | support | finance | custom\n  config       Json\n  generated_at DateTime?\n  generated_by String?\n  result_url   String?\n  created_at   DateTime  @default(now())\n\n  @@index([tenant_id, report_type])\n}\n\n// ═════════════════════════════════════════════\n// AUP — ADMINISTRACIÓN EN UNA PÁGINA\n// ═════════════════════════════════════════════\n\nmodel StrategicPurpose {\n  id         String   @id @default(cuid())\n  tenant_id  String   @unique\n  tenant     Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  vision     String\n  mission    String?\n  values     String[]\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  key_success_factors KeySuccessFactor[]\n}\n\nmodel KsfRelationship {\n  id               String           @id @default(cuid())\n  tenant_id        String\n  team_slot_id     String\n  team_slot        TeamSlot         @relation(fields: [team_slot_id], references: [id], onDelete: Cascade)\n  type             RelationshipType\n  customer_type    CustomerType?\n  name             String\n  internal_slot_id String?\n  expectation      String\n  discovery_method String?\n  created_at       DateTime         @default(now())\n\n  success_areas SuccessArea[]\n\n  @@index([team_slot_id])\n  @@index([tenant_id])\n}\n\nmodel SuccessArea {\n  id              String          @id @default(cuid())\n  tenant_id       String\n  team_slot_id    String\n  relationship_id String\n  relationship    KsfRelationship @relation(fields: [relationship_id], references: [id], onDelete: Cascade)\n  name            String\n  created_at      DateTime        @default(now())\n\n  key_success_factors KeySuccessFactor[]\n\n  @@index([team_slot_id])\n  @@index([relationship_id])\n}\n\nmodel KeySuccessFactor {\n  id                 String               @id @default(cuid())\n  tenant_id          String\n  tenant             Tenant               @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  name               String\n  description        String?\n  unit               String\n  level              KsfLevel\n  purpose_id         String?\n  purpose            StrategicPurpose?    @relation(fields: [purpose_id], references: [id])\n  parent_ksf_id      String?\n  parent_ksf         KeySuccessFactor?    @relation(\"KsfHierarchy\", fields: [parent_ksf_id], references: [id])\n  child_ksfs         KeySuccessFactor[]   @relation(\"KsfHierarchy\")\n  dept_id            String?\n  dept               Department?          @relation(fields: [dept_id], references: [id])\n  team_slot_id       String?\n  team_slot          TeamSlot?            @relation(fields: [team_slot_id], references: [id])\n  origin             KsfOrigin\n  category           KsfCategory\n  success_area_id    String?\n  success_area       SuccessArea?         @relation(fields: [success_area_id], references: [id])\n  measurement_source MeasurementSource\n  measurement_config Json\n  measurement_freq   MeasurementFrequency\n  minimum_level      Float\n  satisfactory_level Float\n  outstanding_level  Float\n  is_active          Boolean              @default(true)\n  created_at         DateTime             @default(now())\n  updated_at         DateTime             @updatedAt\n\n  milestones   KsfMilestone[]\n  measurements GoalMeasurement[]\n\n  @@index([tenant_id, level])\n  @@index([team_slot_id])\n  @@index([dept_id])\n  @@index([parent_ksf_id])\n}\n\nmodel KsfMilestone {\n  id           String           @id @default(cuid())\n  ksf_id       String\n  ksf          KeySuccessFactor @relation(fields: [ksf_id], references: [id], onDelete: Cascade)\n  name         String\n  target_date  DateTime\n  completed_at DateTime?\n  notes        String?\n  created_at   DateTime         @default(now())\n\n  @@index([ksf_id])\n}\n\nmodel EscalationConfig {\n  id                 String   @id @default(cuid())\n  tenant_id          String\n  manager_slot_id    String   @unique\n  manager_slot       TeamSlot @relation(fields: [manager_slot_id], references: [id], onDelete: Cascade)\n  threshold1_periods Int      @default(4)\n  threshold1_levels  Int      @default(2)\n  threshold2_periods Int      @default(8)\n  threshold2_levels  Int      @default(3)\n  rationale          String?\n  updated_at         DateTime @updatedAt\n\n  @@index([tenant_id])\n}\n\nmodel GoalMeasurement {\n  id                             String           @id @default(cuid())\n  ksf_id                         String\n  ksf                            KeySuccessFactor @relation(fields: [ksf_id], references: [id], onDelete: Cascade)\n  team_slot_id                   String?\n  team_slot                      TeamSlot?        @relation(fields: [team_slot_id], references: [id])\n  period                         DateTime\n  actual_value                   Float\n  status                         KsfStatus\n  trend                          Trend\n  consecutive_above_satisfactory Int              @default(0)\n  consecutive_below_minimum      Int              @default(0)\n  snapshot                       Json?\n  created_at                     DateTime         @default(now())\n\n  @@unique([ksf_id, period])\n  @@index([ksf_id])\n  @@index([team_slot_id])\n  @@index([ksf_id, period])\n}\n\nmodel FocusReport {\n  id            String    @id @default(cuid())\n  tenant_id     String\n  tenant        Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  target_level  KsfLevel\n  target_id     String\n  team_slot_id  String?\n  team_slot     TeamSlot? @relation(fields: [team_slot_id], references: [id])\n  period        DateTime\n  ksf_snapshots Json\n  generated_at  DateTime  @default(now())\n\n  @@unique([target_id, period])\n  @@index([tenant_id, target_level])\n  @@index([team_slot_id])\n}\n\nmodel FeedbackReport {\n  id               String   @id @default(cuid())\n  tenant_id        String\n  tenant           Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  team_slot_id     String\n  team_slot        TeamSlot @relation(fields: [team_slot_id], references: [id], onDelete: Cascade)\n  week_start       DateTime\n  positive_results Json\n  negative_results Json\n  generated_at     DateTime @default(now())\n\n  @@unique([team_slot_id, week_start])\n  @@index([tenant_id])\n  @@index([team_slot_id])\n}\n\nmodel ManagementReport {\n  id                String   @id @default(cuid())\n  tenant_id         String\n  tenant            Tenant   @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  manager_slot_id   String\n  manager_slot      TeamSlot @relation(fields: [manager_slot_id], references: [id], onDelete: Cascade)\n  week_start        DateTime\n  zone1_outstanding Json\n  zone2_positives   Json\n  zone3_chronic     Json\n  zone4_negatives   Json\n  generated_at      DateTime @default(now())\n\n  @@unique([manager_slot_id, week_start])\n  @@index([tenant_id])\n  @@index([manager_slot_id])\n}\n\nmodel RecognitionEvent {\n  id                  String             @id @default(cuid())\n  tenant_id           String\n  tenant              Tenant             @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  recognizer_id       String\n  recognizer          TeamSlot           @relation(\"RecognizerSlot\", fields: [recognizer_id], references: [id])\n  recognized_id       String\n  recognized          TeamSlot           @relation(\"RecognizedSlot\", fields: [recognized_id], references: [id])\n  ksf_id              String\n  ksf_name            String\n  consecutive_periods Int\n  week_start          DateTime\n  message             String?\n  channel             RecognitionChannel\n  sent_at             DateTime?\n  created_at          DateTime           @default(now())\n\n  @@index([tenant_id])\n  @@index([recognizer_id])\n  @@index([recognized_id])\n}\n\nmodel GoalSetupStatus {\n  id                 String    @id @default(cuid())\n  tenant_id          String\n  tenant             Tenant    @relation(fields: [tenant_id], references: [id], onDelete: Cascade)\n  target_level       KsfLevel\n  target_id          String    @unique\n  team_slot_id       String?   @unique\n  team_slot          TeamSlot? @relation(fields: [team_slot_id], references: [id])\n  is_complete        Boolean   @default(false)\n  missing_categories String[]\n  unset_goal_levels  String[]\n  has_unique_ksfs    Boolean   @default(false)\n  last_checked_at    DateTime\n\n  @@index([tenant_id, target_level])\n}\n\n// ── AUP Enums ──────────────────────────────────────────────────────────────\n\nenum KsfLevel {\n  COMPANY\n  DEPARTMENT\n  EMPLOYEE\n}\n\nenum KsfCategory {\n  OPERATIONAL\n  COORDINATION\n  STRATEGIC\n}\n\nenum KsfStatus {\n  NO_DATA\n  BELOW_MINIMUM\n  AT_MINIMUM\n  IN_PROGRESS\n  SATISFACTORY\n  OUTSTANDING\n}\n\nenum KsfOrigin {\n  TOP_DOWN\n  BOTTOM_UP\n}\n\nenum MeasurementFrequency {\n  DAILY\n  WEEKLY\n  MONTHLY\n  QUARTERLY\n}\n\nenum MeasurementSource {\n  TASKS_COMPLETION_RATE\n  TASKS_ON_TIME_RATE\n  TASKS_COMPLETED_COUNT\n  MESSAGE_RESPONSE_TIME_AVG\n  MESSAGE_VOLUME\n  PRESENCE_HOURS\n  PRESENCE_ATTENDANCE_RATE\n  PRESENCE_PUNCTUALITY_RATE\n  AGENT_RESOLUTION_RATE\n  AGENT_CONVERSATION_COUNT\n  CRM_CONTACTS_MANAGED\n  CRM_DEALS_CLOSED\n  CRM_DEALS_VALUE\n  TEAM_TASK_COMPLETION_RATE\n  TEAM_RESPONSE_TIME_AVG\n  TEAM_PRESENCE_RATE\n  DEPT_KPIS_IN_GREEN\n  PIPELINE_CONVERSION_RATE\n  PIPELINE_TOTAL_VALUE\n  PROJECT_MILESTONE_PCT\n  REVENUE_GROWTH_RATE\n  CUSTOMER_RETENTION_RATE\n  COST_REDUCTION_PCT\n  INVENTORY_TURNOVER\n  UNIT_COST_VS_COMPETITOR\n  MANUAL\n}\n\nenum RelationshipType {\n  EMPLOYER\n  BOSS\n  SUPPLIER\n  CUSTOMER\n}\n\nenum CustomerType {\n  INTERNAL\n  EXTERNAL\n}\n\nenum Trend {\n  UP\n  DOWN\n  STABLE\n}\n\nenum RecognitionChannel {\n  CAMPUS_PUBLIC_MESSAGE\n  CAMPUS_DIRECT_MESSAGE\n  EMAIL\n  TELEGRAM\n  IN_PERSON\n}\n"
}

